package com.khm.snippets.core.review.crypto

import kotlin.test.Test
import kotlin.test.assertTrue
import kotlin.test.fail

/**
 * The port against verdicts recorded from the shipping Swift code (Swift 6.4, arm64 macOS,
 * CryptoKit and CommonCrypto), on inputs generated by `ReviewInputs(scale = 1)`.
 *
 * Both directions are in here: `rec-seal`, `kw-wrap` and `pw-wrap` lines carry text that
 * Swift sealed with its own nonces and the port must open; `rec-open`, `kw-unwrap` and
 * `pw-unwrap` lines carry text the port sealed and Swift opened (the recorded verdict is
 * what Swift recovered); `rec-seal-nonce` pins the nonce and compares the text itself.
 *
 * Lines that show a known defect are listed in [KnownDefects] and asserted by the tests
 * named there, so that everything else here stays green and keeps guarding.
 */
class SwiftDifferentialTest {

    private fun compare(fixture: String, minimumRows: Int) {
        val rows = ReviewCrypto.rows(fixture)
        assertTrue(rows.size >= minimumRows, "$fixture has only ${rows.size} rows")
        val disagreements = ArrayList<String>()
        var known = 0
        for (row in rows) {
            val fields = row.dropLast(1)
            val expected = row.last()
            val actual = KotlinJudge.disagreement(fields, expected) ?: continue
            if (KnownDefects.covers(fields, expected, actual)) {
                known += 1
                continue
            }
            disagreements += "${fields.joinToString(" ").take(300)}\n    Swift:  ${expected.take(300)}\n    Kotlin: ${actual.take(300)}"
        }
        if (disagreements.isNotEmpty()) {
            fail("$fixture: ${disagreements.size} of ${rows.size} lines disagree with Swift ($known more are known defects):\n" +
                disagreements.take(12).joinToString("\n"))
        }
    }

    @Test fun recordsWrapsAndDerivedValuesAgreeWithSwiftInBothDirections() = compare("crypto.tsv.gz", 1500)

    @Test fun envelopeGrammarAndOpenFailuresAgreeWithSwift() = compare("envelopes.tsv.gz", 800)

    @Test fun base64UuidAndUtf8ReadersAgreeWithSwift() = compare("codecs.tsv.gz", 2800)

    @Test fun recoveryKeysAgreeWithSwift() = compare("recovery.tsv.gz", 2600)

    @Test fun passphraseDerivationAndNormalisationAgreeWithSwift() = compare("passphrase.tsv.gz", 850)

    @Test fun targetedDoublesPrintAsInSwift() = compare("doubles.tsv.gz", 30000)

    @Test fun canonicalJsonParsesAndEmitsAsInSwift() = compare("canonical.tsv.gz", 3200)
}
